"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[740],{5740:function(e,i,t){t.d(i,{h:function(){return a}});let a={meta:{title:"antAI Guardian — Real-Time Voice-Clone Interception & Fraud Defense",description:"High-assurance defensive runtime for telephony and high-stakes banking. Evaluates 14 acoustic, biometric, and linguistic models in sub-2s latency, enforces in-flight transaction holds, and breaks adversarial social engineering.",badge:"SYSTEM CLASSIFICATION: OPERATIONAL // SIH-PS26104 // TACTICAL VOICE SHIELD",nodeId:"#NODE-8765-PRIMARY"},navigation:{brand:"antAI Guardian",classification:"RESTRICTED // PS26104",links:[{label:"Operations Overview",href:"/"},{label:"Threat Capabilities",href:"/features"},{label:"Ingestion Pipeline",href:"/how-it-works"},{label:"SOC Live Console",href:"/dashboard-live"},{label:"Architecture DAG",href:"/dataflow"},{label:"Forensic Lab",href:"/demo"}],cta:{label:"Access SOC Console",href:"/dashboard-live"}},hero:{headline:"Real-time voice-clone interception and transaction freeze.",subhead:"Enterprise defensive runtime for critical voice and banking channels. Continuously inspects live audio streams, verifies speaker voiceprints, computes multi-model adversarial risk in sub-2s latency, and locks down fraudulent transaction actions before panic takes hold.",telemetry:[{label:"INSPECTION LATENCY",value:"< 1.8s",sub:"Deterministic SLA ceiling"},{label:"DETECTION ENSEMBLE",value:"14 Models",sub:"Multi-modal LangGraph DAG"},{label:"ARBITRATION POLICY",value:"Zero-Trust",sub:"Dead-zone calibrated fusion"},{label:"HOLD ENFORCEMENT",value:"In-Flight",sub:"Non-blocking sovereign control"}],ctaPrimary:"Launch SOC Live Console",ctaSecondary:"Inspect Architecture DAG",pulseGuide:{title:"Real-Time Threat Level Telemetry",safe:{score:14,band:"SECURE / NORMAL",title:"Normal Biometric Acoustics",description:"Acoustic spectrum matches natural human glottal pulses. Speaker voiceprint verified (Cosine: 0.96)."},verify:{score:56,band:"ADVISORY / VERIFY",title:"Biometric Drift Detected",description:"Unenrolled voice or borderline phase distortion. Secondary out-of-band verification required."},critical:{score:89,band:"CRITICAL / HOLD ACTIVE",title:"Synthetic Clone + Fund Transfer",description:"AST+wav2vec2 ensemble detects AI voice (94%) paired with high-pressure ₹8,50,000 transfer ask."}}},features:[{id:"realtime",title:"Sub-2.0s Wire-Speed Ingestion",tag:"DETERMINISTIC LATENCY",description:"Engineered for active voice streams: 0.4–2.0s rolling Silero VAD chunks feeding concurrent asynchronous inference workers. Computes composite risk updates and emits mitigation directives before the caller can finish pressure demands.",metric:"< 1.8s",metricLabel:"Hard roundtrip SLA ceiling"},{id:"dual-model-voice",title:"Dual-Model Acoustic Clone Defeat",tag:"SPECTRAL ENSEMBLE",description:"Combines Audio Spectrogram Transformer (AST-ASVspoof5) with self-supervised wav2vec2 backends. Enforces a dead-zone ramp (floor 0.78 → ceil 0.95, max +60 score) so only genuine vocoder artifacts trigger high-threat alarms.",metric:"95M + 90M",metricLabel:"Transformer parameter backbone"},{id:"voiceprint-verify",title:"Speaker Voiceprint Biometric Attestation",tag:"ZERO-TRUST BIOMETRICS",description:"ECAPA-TDNN deep speaker embedding extractor calculates cosine vector distance against enrolled trusted family, corporate, or branch authority profiles. Immediately flags impersonators claiming trusted identities.",metric:"192-dim",metricLabel:"Strict cosine similarity match"},{id:"scenario-thresholds",title:"Adaptive Threat Matrix Thresholds",tag:"POLICY ARBITRATION",description:"Context-aware sensitivity matrix automatically adjusts cutoffs: Routine Call (verify @ 75, alert @ 90), High-Value Transaction (verify @ 50, alert @ 70), and Privileged Access (verify @ 40, alert @ 60). Fetched live from config.",metric:"3 Tiers",metricLabel:"Context-specific risk policies"},{id:"privacy-first",title:"Zero-Knowledge Ephemeral Buffer Architecture",tag:"CRYPTOGRAPHIC HYGIENE",description:"Zero raw call audio is ever stored on disk or transmitted to untrusted endpoints. Phone numbers are salted with SHA-256 before collective database lookups. Audio ring buffers auto-purge upon call teardown with TTL eviction.",metric:"Salted SHA-256",metricLabel:"Zero persistent audio footprint"},{id:"freeze-controller",title:"Non-Repudiation In-Flight Action Intercept",tag:"ACTIVE MITIGATION",description:"Breaks the reflexive panic loop without silent blocking. When risk clears critical thresholds and an actionable ask is flagged, an immediate hold directive pauses OTP visibility, funds transfers, or remote credential grants.",metric:"100% Sovereign",metricLabel:"Explicit user confirm / override"}],howItWorks:{title:"5-Stage Forensic Telemetry & Interception Pipeline",subhead:"End-to-end data pipeline from initial WebRTC stream tap to deterministic LangGraph action interception.",steps:[{step:"01",name:"Media Ingress & Stream Tap",time:"< 40 ms",summary:"Read-only fork from Android WebRTC SFU / CallScreening tap.",detail:"Media frames flow through the server relay. A non-blocking tap forks 16kHz mono PCM chunks into memory queues without degrading call jitter or affecting codec negotiation."},{step:"02",name:"Silero VAD Speech Segmentation",time:"15–30 ms",summary:"0.4–2.0s voiced speech slice extraction and silence eviction.",detail:"Voiced audio segments are stripped of acoustic silence. Concurrent workers pass speech slices into streaming ASR and acoustic deepfake pipelines simultaneously."},{step:"03",name:"14-Model Multi-Modal Evaluation",time:"120–220 ms",summary:"Parallelized acoustic, biometric, semantic, and facial models.",detail:"Concurrent inference: AST + wav2vec2 synthetic probability, ECAPA-TDNN speaker similarity, scam pattern NLP classifier, psychological urgency scorer, and lip-sync AV correlation."},{step:"04",name:"Deterministic LangGraph Fusion",time:"< 10 ms",summary:"Hard/soft signal partitioning and corroboration verification.",detail:"Zero black-box guesses: hard signals (identity mismatch, high deepfake prob) add up to +60. Soft signals require at least 2 independent corroborations to clear verify (capped at 39 if solo)."},{step:"05",name:"Forensic Reasoning & Hold Directive",time:"180–350 ms",summary:"Synthesized 'why' verdict + WebSocket hold push to client.",detail:"Fast-path template or Groq/Gemini/local Qwen fallback generates natural-language guidance in English and Hindi, while the Intercept Controller halts high-risk in-app actions."}]},scenarios:{routine_call:{label:"Routine Telecom Channel",description:"Standard peer-to-peer or customer service communications.",verify_at:75,critical_at:90},high_value_txn:{label:"High-Value Transaction ($/₹)",description:"Wire transfers, NEFT/RTGS, and financial authorizations.",verify_at:50,critical_at:70},privileged_access:{label:"Privileged Access / Auth",description:"Credential resets, IT remote control, and MFA token approvals.",verify_at:40,critical_at:60}},pipelineNodes:[{id:"phone_webrtc",label:"Terminal Ingress (WebRTC)",category:"Ingress",latencyBudget:"< 50 ms",modelInfo:"Android WebRTC Client / CallScreeningService",failureBehavior:"Degrades to local on-device screening heuristics with offline UI warning.",description:"Captures 16kHz mono PCM audio from local audio HAL. Relays stream to SFU while maintaining real-time telemetry overlay."},{id:"sfu_relay",label:"SFU Media Relay Tap",category:"Ingress",latencyBudget:"20–40 ms",modelInfo:"Selective Forwarding Unit (Go/C++ media stack)",failureBehavior:"Peer-to-peer direct relay without server-side forensic inspection.",description:"Relays live call audio and forks a read-only stream tap into the inspection queue without duplicating client upload bandwidth."},{id:"vad_segmentation",label:"Silero VAD Segmentation",category:"Pre-processing",latencyBudget:"10–30 ms",modelInfo:"Silero VAD v4 ONNX (0.4–2.0s speech window)",failureBehavior:"Passes raw fixed-length 1s chunks without acoustic silence suppression.",description:"Evicts ambient noise and dead silence. Emits clean speech frames to prevent empty buffers from corrupting transformer caches."},{id:"asr_engine",label:"Streaming ASR Engine",category:"Feature Extraction",latencyBudget:"150–220 ms",modelInfo:"Deepgram Nova-2 (hosted) / Whisper-Base int8 (local CPU)",failureBehavior:"Text triage bypassed; pipeline operates solely on acoustic + biometric signals.",description:"Transcribes incoming speech chunks into a live timestamped text stream with word-level confidence metrics."},{id:"voice_deepfake_ensemble",label:"AST + wav2vec2 Ensemble",category:"Inference",latencyBudget:"120–180 ms",modelInfo:"AST-ASVspoof5 (95M) + wav2vec2-large (90M) / Velma hosted API",failureBehavior:"Outputs null (honest '—' unavailable state, never zero); warns SOC operator.",description:"Analyzes spectral phase distortion, vocoder artifacts, and pitch anomalies. Calculates synthetic probability with dead-zone agreement gating."},{id:"speaker_verify",label:"ECAPA-TDNN Biometric Verify",category:"Inference",latencyBudget:"40–70 ms",modelInfo:"ECAPA-TDNN 192-dim speaker embeddings",failureBehavior:"Identity mismatch marked False (neutral); surfaces 'No voiceprint on record'.",description:"Extracts speaker embeddings and calculates cosine similarity against enrolled trusted authority or family voiceprints."},{id:"video_detectors",label:"FaceMesh & Lip-Sync AV",category:"Inference",latencyBudget:"80–140 ms",modelInfo:"MediaPipe FaceMesh + SyncNet Temporal AV Cross-Correlation",failureBehavior:"Video signals set to null; pipeline operates strictly on acoustic stream.",description:"For video calls, samples 5–8 fps to detect facial warping, abnormal blink rates, and phoneme-viseme audio-visual desynchronization."},{id:"text_classifiers",label:"Scam NLP & Urgency Scorer",category:"Inference",latencyBudget:"30–50 ms",modelInfo:"Fine-tuned MiniLM fraud classifier + rule-based urgency keyword tree",failureBehavior:"Gated by low-content triage; skips greetings ('hi/hello') to prevent false triggers.",description:"Calculates fraud script probability and extracts psychological pressure triggers ('police custody', 'immediate wire', 'account seized')."},{id:"langgraph_fusion",label:"LangGraph Fusion Node",category:"Orchestration",latencyBudget:"< 10 ms",modelInfo:"Deterministic dead-zone ramp weighting engine",failureBehavior:"Degrades to sequential fallback graph with safe-node decorators.",description:"Fuses hard signals (+60 max) and soft signals. Applies strict corroboration rule: caps risk below 39 if soft signals lack independent corroboration."},{id:"decision_node",label:"Deterministic Decision Node",category:"Policy",latencyBudget:"< 5 ms",modelInfo:"Config-driven threshold matrix",failureBehavior:"Defaults to passive log state; never blocks without clear signal triggers.",description:"Evaluates fused risk against active scenario. Dispatches state: PASSIVE (<40), VERIFY (40–69), ESCALATE (≥70 no request), or FREEZE (≥70 + actionable request)."},{id:"llm_reasoner",label:"LLM Reasoning Engine",category:"Explanation",latencyBudget:"180–350 ms",modelInfo:"Groq (Llama-3-8B) → Gemini-1.5 → OpenRouter → Local Qwen2.5-3B GGUF",failureBehavior:"Falls back to pre-compiled deterministic template verdict (0ms runtime).",description:"Synthesizes active cues into forensic explanation and protocol steps in English and Hindi."},{id:"freeze_controller",label:"In-Flight Freeze Controller",category:"Defense Execution",latencyBudget:"< 15 ms",modelInfo:"Stateful hold directive dispatcher",failureBehavior:"Hold expires safely after TTL; logs incident for SOC review.",description:"Transmits real-time hold directives over WebSocket to client UI, locking down critical transaction buttons."},{id:"storage_reporting",label:"Forensic Audit & Encrypted DB",category:"Storage",latencyBudget:"10–20 ms",modelInfo:"SQLite / PostgreSQL with salted SHA-256 phone hash index",failureBehavior:"Local client caches incident in Room DB; syncs when connectivity restores.",description:"Generates post-call forensic timeline and FIR complaint draft for cybercrime.gov.in (Helpline 1930)."}],demoScenarios:[{id:"clone-bank",title:"Attack Vector A: Branch Authority Voice Clone",scenario:"high_value_txn",description:"Synthetic voice impersonating a branch manager demanding an urgent ₹8,50,000 NEFT transfer.",steps:[{t:0,text:"Good afternoon. This is Rahul Sharma, Branch Manager at State Bank.",risk:14,band:"passive",voicefake:.12,urgency:10,match:.88},{t:2,text:"We have an emergency audit on your commercial account right now.",risk:38,band:"passive",voicefake:.45,urgency:55,match:.72},{t:4,text:"You must transfer ₹8,50,000 immediately to the safe clearing escrow account.",risk:71,band:"critical",voicefake:.89,urgency:88,match:.18},{t:6,text:"Do not disconnect or alert your local branch or the account will be locked.",risk:89,band:"critical",voicefake:.94,urgency:96,match:.08,freeze:!0}]},{id:"grandchild-emergency",title:"Attack Vector B: Kinship Distress Clone Impersonation",scenario:"routine_call",description:"Cloned voice of a family member crying after a car accident, asking for immediate bail money.",steps:[{t:0,text:"Dad... please help me, I had a terrible accident...",risk:28,band:"passive",voicefake:.52,urgency:40,match:.65},{t:2,text:"The police inspector is here, they are going to take my phone away!",risk:62,band:"verify",voicefake:.81,urgency:92,match:.22},{t:4,text:"Send ₹50,000 to this UPI number right now before they file the FIR!",risk:86,band:"critical",voicefake:.93,urgency:98,match:.12,freeze:!0}]},{id:"safe-routine",title:"Baseline Vector C: Normal Enrolled Contact Call",scenario:"routine_call",description:"Natural conversational speech from an enrolled family contact.",steps:[{t:0,text:"Hi, just calling to check if you reached home safely.",risk:8,band:"passive",voicefake:.04,urgency:5,match:.96},{t:2,text:"Don't forget to bring the groceries for dinner tonight.",risk:10,band:"passive",voicefake:.05,urgency:8,match:.98},{t:4,text:"See you in an hour. Bye!",risk:12,band:"passive",voicefake:.03,urgency:6,match:.97}]}]}}}]);